"filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/context/ThemeContext.tsx",
"content": "import { createContext, useContext, useEffect, useState, ReactNode } from 'react';

interface ThemeContextValue {
theme: 'light' | 'dark';
toggleTheme: () => void;
}

const ThemeContext = createContext(undefined);

const THEME_STORAGE_KEY = 'subscription-dashboard-theme';

export function ThemeProvider({ children }: { children: ReactNode }) {
const [theme, setTheme] = useState(() => {
	if (typeof window === 'undefined') return 'dark';
	const stored = window.localStorage.getItem(THEME_STORAGE_KEY) as 'light' | 'dark' | null;
	if (stored === 'light' || stored === 'dark') return stored;
	return 'dark';
});

useEffect(() => {
	if (typeof document === 'undefined') return;
	const root = document.documentElement;
	if (theme === 'dark') {
	root.classList.add('dark');
	root.classList.remove('light');
	} else {
	root.classList.remove('dark');
	root.classList.add('light');
	}
	window.localStorage.setItem(THEME_STORAGE_KEY, theme);
}, [theme]);

const toggleTheme = () => {
	setTheme((prev) => (prev === 'dark' ? 'light' : 'dark'));
};

return {children};
}

export function useTheme() {
const ctx = useContext(ThemeContext);
if (!ctx) throw new Error('useTheme must be used within ThemeProvider');
return ctx;
}
"
}


