{
"filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/utils/subscriptionStats.ts",
"content": "import { Subscription, SubscriptionCategory } from '../types/subscription';

export function getTotalMonthly(subscriptions: Subscription[]): number {
return subscriptions.reduce((sum, s) => sum + (isFinite(s.price) ? s.price : 0), 0);
}

export function getMostExpensive(subscriptions: Subscription[]): Subscription | null {
if (!subscriptions.length) return null;
return subscriptions.reduce((max, s) => (s.price > max.price ? s : max), subscriptions[0]);
}

export function getNextDue(subscriptions: Subscription[]): Subscription | null {
if (!subscriptions.length) return null;
const today = new Date();
const upcoming = [...subscriptions]
	.map((s) => ({
	sub: s,
	date: new Date(s.dueDate),
	}))
	.filter(({ date }) => !isNaN(date.getTime()))
	.sort((a, b) => a.date.getTime() - b.date.getTime());

if (!upcoming.length) return null;

const next = upcoming.find(({ date }) => date >= today) ?? upcoming[0];
return next.sub;
}

export function getSpendByCategory(subscriptions: Subscription[]): Record {
const base: Record = {
	streaming: 0,
	trabalho: 0,
	saude: 0,
};

return subscriptions.reduce((acc, s) => {
	if (acc[s.category] === undefined) return acc;
	acc[s.category] += isFinite(s.price) ? s.price : 0;
	return acc;
}, base);
}

export function formatCurrencyBRL(value: number): string {
return new Intl.NumberFormat('pt-BR', {
	style: 'currency',
	currency: 'BRL',
	maximumFractionDigits: 2,
}).format(value || 0);
}

export function formatDateBR(dateStr: string): string {
const d = new Date(dateStr);
if (isNaN(d.getTime())) return '-';
return d.toLocaleDateString('pt-BR', {
	day: '2-digit',
	month: '2-digit',
	year: 'numeric',
});
}
"
}


{
"filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/context/SubscriptionContext.tsx",
"content": "import { createContext, useContext, useEffect, useMemo, useState, ReactNode } from 'react';
import { Subscription } from '../types/subscription';
import { v4 as uuidv4 } from 'uuid';

interface SubscriptionContextValue {
subscriptions: Subscription[];
addSubscription: (payload: Omit) => void;
updateSubscription: (id: string, updates: Omit) => void;
deleteSubscription: (id: string) => void;
}

const STORAGE_KEY = 'subscription-dashboard-data';

const SubscriptionContext = createContext(undefined);

const seedData: Subscription[] = [
{
	id: 'seed-1',
	name: 'Netflix',
	price: 39.9,
	dueDate: new Date().toISOString().slice(0, 10),
	category: 'streaming',
},
{
	id: 'seed-2',
	name: 'ChatGPT Plus',
	price: 99.9,
	dueDate: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
	category: 'trabalho',
},
{
	id: 'seed-3',
	name: 'Academia',
	price: 120,
	dueDate: new Date(Date.now() + 10 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
	category: 'saude',
},
];

export function SubscriptionProvider({ children }: { children: ReactNode }) {
const [subscriptions, setSubscriptions] = useState(() => {
	if (typeof window === 'undefined') return seedData;
	try {
	const raw = window.localStorage.getItem(STORAGE_KEY);
	if (!raw) return seedData;
	const parsed = JSON.parse(raw) as Subscription[];
	if (!Array.isArray(parsed)) return seedData;
	return parsed;
	} catch {
	return seedData;
	}
});

useEffect(() => {
	if (typeof window === 'undefined') return;
	window.localStorage.setItem(STORAGE_KEY, JSON.stringify(subscriptions));
}, [subscriptions]);

const addSubscription: SubscriptionContextValue['addSubscription'] = (payload) => {
	setSubscriptions((current) => [
	{
		...payload,
		id: uuidv4(),
	},
	...current,
	]);
};

const updateSubscription: SubscriptionContextValue['updateSubscription'] = (id, updates) => {
	setSubscriptions((current) => current.map((s) => (s.id === id ? { ...updates, id } : s)));
};

const deleteSubscription: SubscriptionContextValue['deleteSubscription'] = (id) => {
	setSubscriptions((current) => current.filter((s) => s.id !== id));
};

const value = useMemo(
	() => ({ subscriptions, addSubscription, updateSubscription, deleteSubscription }),
	[subscriptions],
);

return {children};
}

export function useSubscriptions() {
const ctx = useContext(SubscriptionContext);
if (!ctx) throw new Error('useSubscriptions must be used within SubscriptionProvider');
return ctx;
}
"
}


