"content": "import { Edit2, Trash2 } from 'lucide-react';
import { useSubscriptions } from '../../context/SubscriptionContext';
import { Subscription } from '../../types/subscription';
import { formatCurrencyBRL, formatDateBR } from '../../utils/subscriptionStats';

interface SubscriptionTableProps {
onEdit: (subscription: Subscription) => void;
onDelete: (subscription: Subscription) => void;
}

const categoryLabel: Record = {
streaming: 'Streaming',
trabalho: 'Trabalho',
saude: 'Saúde',
};

export function SubscriptionTable({ onEdit, onDelete }: SubscriptionTableProps) {
const { subscriptions } = useSubscriptions();

if (!subscriptions.length) {
	return (

		Nenhuma assinatura cadastrada ainda. Comece adicionando seus serviços recorrentes.

	);
}

return (


		Suas assinaturas





			Serviço
			Valor mensal
			Vencimento
			Categoria
			Ações



			{subscriptions.map((s) => (


				{s.name}
				{s.notes && {s.notes}}

				{formatCurrencyBRL(s.price)}
				{formatDateBR(s.dueDate)}


					{categoryLabel[s.category]}




					onEdit(s)}
					className=\"inline-flex h-8 w-8 items-center justify-center rounded-full border border-slate-700/70 text-foreground-muted transition hover:border-sky-500/80 hover:text-sky-400\"
					>


					onDelete(s)}
					className=\"inline-flex h-8 w-8 items-center justify-center rounded-full border border-slate-700/70 text-foreground-muted transition hover:border-rose-500/80 hover:text-rose-400\"
					>





			))}





		{subscriptions.map((s) => (



				{s.name}
				{s.notes && {s.notes}}

			{formatCurrencyBRL(s.price)}


			Vence em {formatDateBR(s.dueDate)}

				{categoryLabel[s.category]}



			onEdit(s)}
				className=\"inline-flex h-8 w-8 items-center justify-center rounded-full border border-slate-700/70 text-foreground-muted transition hover:border-sky-500/80 hover:text-sky-400\"
			>


			onDelete(s)}
				className=\"inline-flex h-8 w-8 items-center justify-center rounded-full border border-slate-700/70 text-foreground-muted transition hover:border-rose-500/80 hover:text-rose-400\"
			>




		))}


);
}
"
}


