"filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/components/subscriptions/AddEditSubscriptionModal.tsx",
"content": "import { FormEvent, useEffect, useState } from 'react';
import { Subscription, SubscriptionCategory } from '../../types/subscription';

interface BaseValues {
name: string;
price: string;
dueDate: string;
category: SubscriptionCategory;
notes: string;
}

interface AddEditSubscriptionModalProps {
mode: 'add' | 'edit';
initial?: Subscription | null;
open: boolean;
onClose: () => void;
onSubmit: (values: Omit) => void;
}

const emptyValues: BaseValues = {
name: '',
price: '',
dueDate: '',
category: 'streaming',
notes: '',
};

export function AddEditSubscriptionModal({ mode, initial, open, onClose, onSubmit }: AddEditSubscriptionModalProps) {
const [values, setValues] = useState(emptyValues);
const [errors, setErrors] = useState>>({});

useEffect(() => {
	if (open) {
	if (mode === 'edit' && initial) {
		setValues({
		name: initial.name,
		price: initial.price.toString(),
		dueDate: initial.dueDate,
		category: initial.category,
		notes: initial.notes ?? '',
		});
	} else {
		setValues(emptyValues);
	}
	setErrors({});
	}
}, [open, mode, initial]);

if (!open) return null;

const validate = (): boolean => {
	const nextErrors: Partial> = {};
	if (!values.name.trim()) nextErrors.name = 'Informe o nome do serviço';
	if (!values.price.trim()) {
	nextErrors.price = 'Informe um valor mensal';
	} else {
	const num = Number(values.price.replace(',', '.'));
	if (!isFinite(num) || num  {
	e.preventDefault();
	if (!validate()) return;

	const num = Number(values.price.replace(',', '.'));

	onSubmit({
	name: values.name.trim(),
	price: num,
	dueDate: values.dueDate,
	category: values.category,
	notes: values.notes.trim() || undefined,
	});
	onClose();
};

const handleBackdropClick = (e: React.MouseEvent) => {
	if (e.target === e.currentTarget) onClose();
};

return (



		{mode === 'add' ? 'Adicionar assinatura' : 'Editar assinatura'}


		Preencha os campos para controlar este serviço recorrente.




			Nome do serviço

			setValues((v) => ({ ...v, name: e.target.value }))}
			className={`w-full rounded-xl border bg-slate-950/60 px-3 py-2 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background ${
				errors.name ? 'border-rose-500/70' : 'border-slate-800/80'
			}`}
			placeholder=\"Ex.: Netflix, Spotify, Academia\"
			/>
			{errors.name && {errors.name}}





				Valor mensal (R$)

			setValues((v) => ({ ...v, price: e.target.value }))}
				className={`w-full rounded-xl border bg-slate-950/60 px-3 py-2 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background ${
				errors.price ? 'border-rose-500/70' : 'border-slate-800/80'
				}`}
				placeholder=\"Ex.: 39,90\"
			/>
			{errors.price && {errors.price}}



				Vencimento

			setValues((v) => ({ ...v, dueDate: e.target.value }))}
				className={`w-full rounded-xl border bg-slate-950/60 px-3 py-2 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background ${
				errors.dueDate ? 'border-rose-500/70' : 'border-slate-800/80'
				}`}
			/>
			{errors.dueDate && {errors.dueDate}}





			Categoria

			setValues((v) => ({ ...v, category: e.target.value as SubscriptionCategory }))}
			className={`w-full rounded-xl border bg-slate-950/60 px-3 py-2 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background ${
				errors.category ? 'border-rose-500/70' : 'border-slate-800/80'
			}`}
			>
			Streaming
			Trabalho
			Saúde

			{errors.category && {errors.category}}




			Observações (opcional)

			setValues((v) => ({ ...v, notes: e.target.value }))}
			rows={3}
			className=\"w-full resize-none rounded-xl border border-slate-800/80 bg-slate-950/60 px-3 py-2 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background\"
			placeholder=\"Ex.: Plano familiar, renovar em caso de promoção, etc.\"
			/>




			Cancelar


			{mode === 'add' ? 'Adicionar' : 'Salvar alterações'}





);
}
"
}


