"content": "import { Subscription } from '../../types/subscription';

interface ConfirmDeleteDialogProps {
open: boolean;
subscription: Subscription | null;
onCancel: () => void;
onConfirm: () => void;
}

export function ConfirmDeleteDialog({ open, subscription, onCancel, onConfirm }: ConfirmDeleteDialogProps) {
if (!open || !subscription) return null;

const handleBackdropClick = (e: React.MouseEvent) => {
	if (e.target === e.currentTarget) onCancel();
};

return (


		Remover assinatura

		Tem certeza que deseja remover {subscription.name} do
		seu painel? Essa ação não pode ser desfeita.



			Cancelar


			Excluir




);
}
"
}


