import { ReactNode } from 'react';
import { Sidebar } from './Sidebar';

export function AppLayout({ header, children }: { header: ReactNode; children: ReactNode }) {
return (



		{header}
		{children}


);
}

import { Moon, Sun } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';

export function ThemeToggle() {
const { theme, toggleTheme } = useTheme();

const isDark = theme === 'dark';

return (




);
}

export type SubscriptionCategory = 'streaming' | 'trabalho' | 'saude';

export interface Subscription {
id: string;
name: string;
price: number;
dueDate: string; // ISO string
category: SubscriptionCategory;
notes?: string;
}

/** @type {import('tailwindcss').Config} */
export default {
content: [],
theme: {
	extend: {},
},
plugins: [],
}

import { useState } from 'react';
import { AppLayout } from './components/layout/AppLayout';
import { Header } from './components/layout/Header';
import { SummaryCards } from './components/subscriptions/SummaryCards';
import { CategorySpendChart } from './components/charts/CategorySpendChart';
import { SubscriptionTable } from './components/subscriptions/SubscriptionTable';
import { AddEditSubscriptionModal } from './components/subscriptions/AddEditSubscriptionModal';
import { ConfirmDeleteDialog } from './components/subscriptions/ConfirmDeleteDialog';
import { useSubscriptions } from './context/SubscriptionContext';
import { Subscription } from './types/subscription';

function DashboardContent(props: { onRequestAdd: () => void }) {
const { addSubscription, updateSubscription, deleteSubscription } = useSubscriptions();

const [editing, setEditing] = useState(null);
const [deleteTarget, setDeleteTarget] = useState(null);

const handleEditSubmit = (payload: Omit) => {
	if (!editing) return;
	updateSubscription(editing.id, payload);
	setEditing(null);
};

const handleConfirmDelete = () => {
	if (!deleteTarget) return;
	deleteSubscription(deleteTarget.id);
	setDeleteTarget(null);
};

return (




	 setEditing(sub)}
		onDelete={(sub) => setDeleteTarget(sub)}
		onRequestAdd={props.onRequestAdd}
	/>

	 setEditing(null)}
		onSubmit={handleEditSubmit}
		initialData={editing || undefined}
	/>

	 setDeleteTarget(null)}
		onConfirm={handleConfirmDelete}
	/>

);
}

function App() {
const [addModalOpen, setAddModalOpen] = useState(false);
const { addSubscription } = useSubscriptions();

const handleAddSubmit = (payload: Omit) => {
	addSubscription(payload);
	setAddModalOpen(false);
};

return (
	<AppLayout header={}>
	 setAddModalOpen(true)} />
	 setAddModalOpen(false)}
		onSubmit={handleAddSubmit}
	/>

);
}

export default App;

